    def _do_req(self, inputreq, wb_url, kwargs, skip_record):
        req_data = inputreq.reconstruct_request(wb_url.url)
        headers = {'Content-Length': str(len(req_data)),
                   'Content-Type': 'application/request'}
        headers.update(inputreq.warcserver_headers)
        if skip_record:
            headers['Recorder-Skip'] = '1'
        if wb_url.is_latest_replay():
            closest = 'now'
        else:
            closest = wb_url.timestamp
        params = {'url': wb_url.url, 'closest': closest, 'matchType': 'exact'}
        if wb_url.mod == 'vi_':
            params['content_type'] = self.VIDEO_INFO_CONTENT_TYPE
        upstream_url = self.get_upstream_url(wb_url, kwargs, params)
        r = requests.post(upstream_url,
                          data=BytesIO(req_data),
                          headers=headers,
                          stream=True)
        return r
    def do_query(self, wb_url, kwargs):
        """Performs the timemap query request for the supplied WbUrl
        returning the response
        :param WbUrl wb_url: The WbUrl to be queried
        :param dict kwargs: Optional keyword arguments
        :return: The queries response
        :rtype: requests.Response
        """
        params = {
            'url': wb_url.url,
            'output': kwargs.get('output', 'json'),
            'from': wb_url.timestamp,
            'to': wb_url.end_timestamp
        }
        if 'memento_format' in kwargs:
            params['memento_format'] = kwargs['memento_format']
        if 'limit' in kwargs:
            params['limit'] = kwargs['limit']
        upstream_url = self.get_upstream_url(wb_url, kwargs, params)
        upstream_url = upstream_url.replace('/resource/postreq', '/index')
        r = requests.get(upstream_url)
        return r
    def load_index(self, params):
        """Loads the xml query index based on the supplied params
        :param dict[str, str] params: The query params
        :return: A list or generator of cdx objects
        :raises NotFoundException: If the query url is not found
        or the results of the query returns no cdx entries
        :raises BadRequestException: If the match type is not exact or prefix
        """
        closest = params.get('closest')
        url = params.get('url', '')
        matchType = params.get('matchType', 'exact')
        if matchType == 'exact':
            query = self.EXACT_QUERY
        elif matchType == 'prefix':
            query = self.PREFIX_QUERY
        else:
            raise BadRequestException('matchType={0} is not supported'.format(matchType=matchType))
        try:
            limit = params.get('limit')
            if limit:
                query = 'limit:{0} '.format(limit) + query
            query_url = self.query_api_url + '?q=' + quote_plus(query + quote_plus(url))
            self.logger.debug("Running query: %s" % query_url)
            response = self.session.get(query_url)
            response.raise_for_status()
            results = etree.fromstring(response.content)
            items = results.find('results')
        except Exception:
            if self.logger.getEffectiveLevel() == logging.DEBUG:
                import traceback
                traceback.print_exc()
            raise NotFoundException('url {0} not found'.format(url))
        if not items:
            raise NotFoundException('url {0} not found'.format(url))
        items = items.findall('result')
        if matchType == 'exact':
            cdx_iter = [self.convert_to_cdx(item) for item in items]
            if closest:
                cdx_iter = cdx_sort_closest(closest, cdx_iter, limit=10000)
        else:
            cdx_iter = self.prefix_query_iter(items)
        return cdx_iter
def canonicalize(url, surt_ordered=True):
    """
    Canonicalize url and convert to surt
    If not in surt ordered mode, convert back to url form
    as surt conversion is currently part of canonicalization
    >>> canonicalize('http://example.com/path/file.html', surt_ordered=True)
    'com,example)/path/file.html'
    >>> canonicalize('http://example.com/path/file.html', surt_ordered=False)
    'example.com/path/file.html'
    >>> canonicalize('urn:some:id')
    'urn:some:id'
    """
    try:
        key = surt.surt(url)
    except Exception as e:
        if url.startswith('urn:'):
            return url
        raise UrlCanonicalizeException('Invalid Url: ' + url)
    if not surt_ordered:
        key = unsurt(key)
    return key
