def custom_links(context, obj):
    """
    Render all applicable links for the given object.
    """
    content_type = ContentType.objects.get_for_model(obj)
    links = CustomLink.objects.filter(content_type=content_type)
    if not links:
        return ""
    link_context = {
        "obj": obj,
        "debug": context.get("debug", False),
        "request": context["request"],
        "user": context["user"],
        "perms": context["perms"],
    }
    template_code = mark_safe("")
    group_names = OrderedDict()
    for cl in links:
        if cl.group_name and cl.group_name in group_names:
            group_names[cl.group_name].append(cl)
        elif cl.group_name:
            group_names[cl.group_name] = [cl]
        else:
            try:
                text_rendered = render_jinja2(cl.text, link_context)
                if text_rendered:
                    link_rendered = render_jinja2(cl.target_url, link_context)
                    link_target = ' target="_blank"' if cl.new_window else ""
                    template_code += format_html(
                        LINK_BUTTON, link_rendered, link_target, cl.button_class, text_rendered
                    )
            except Exception as e:
                template_code += format_html(
                    '<a class="btn btn-sm btn-default" disabled="disabled" title="{}">'
                    '<i class="mdi mdi-alert"></i> {}</a>\n',
                    e,
                    cl.name,
                )
    for group, links in group_names.items():
        links_rendered = mark_safe("")
        for cl in links:
            try:
                text_rendered = render_jinja2(cl.text, link_context)
                if text_rendered:
                    link_target = ' target="_blank"' if cl.new_window else ""
                    link_rendered = render_jinja2(cl.target_url, link_context)
                    links_rendered += format_html(GROUP_LINK, link_rendered, link_target, text_rendered)
            except Exception as e:
                links_rendered += format_html(
                    '<li><a disabled="disabled" title="{}"><span class="text-muted">'
                    '<i class="mdi mdi-alert"></i> {}</span></a></li>',
                    e,
                    cl.name,
                )
        if links_rendered:
            template_code += format_html(GROUP_BUTTON, links[0].button_class, group, links_rendered)
    return template_code

class ReverseProxiedEnvironment:
    def __call__(self, environ):
        def retrieve_header(header_type):
            candidates = getattr(self, "_headers_" + header_type, [])
            fallback = getattr(self, "_fallback_" + header_type, None)
            for candidate in candidates:
                value = environ.get(candidate, None)
                if value is not None:
                    return value
            else:
                return fallback
        def host_to_server_and_port(host, scheme):
            if host is None:
                return None, None
            default_port = "443" if scheme == "https" else "80"
            host = host.strip()
            if ":" in host:
                if host[0] == "[":
                    address_end = host.find("]")
                    if address_end == -1:
                        return None, None
                    server = host[1:address_end]
                    tail = host[address_end + 1 :]
                    if len(tail) and tail[0] == ":":
                        port = tail[1:]
                    else:
                        port = default_port
                elif self.__class__.valid_ip(host):
                    server = host
                    port = default_port
                else:
                    server, port = host.rsplit(":", 1)
            else:
                server = host
                port = default_port
            return server, port
        prefix = retrieve_header("prefix")
        if prefix is not None:
            environ["SCRIPT_NAME"] = prefix
            path_info = environ["PATH_INFO"]
            if path_info.startswith(prefix):
                environ["PATH_INFO"] = path_info[len(prefix) :]
        scheme = retrieve_header("scheme")
        if scheme is not None and "," in scheme:
            scheme, _ = map(lambda x: x.strip(), scheme.split(",", 1))
        if scheme is not None:
            environ["wsgi.url_scheme"] = scheme
        url_scheme = environ["wsgi.url_scheme"]
        host = retrieve_header("host")
        if host is not None:
            server, port = host_to_server_and_port(host, url_scheme)
            environ["HTTP_HOST"] = host
            environ["SERVER_NAME"] = server
            environ["SERVER_PORT"] = port
