HASH_READ_SIZE = 65536
def hash_filelike(filelike):
    """
    Compute the hash of a file-like object, without loading it all into memory.
    """
    file_pos = 0
    if hasattr(filelike, "tell"):
        file_pos = filelike.tell()
    try:
        filelike.seek(0)
    except (AttributeError, UnsupportedOperation):
        pass
    hasher = sha1()
    while True:
        data = filelike.read(HASH_READ_SIZE)
        if not data:
            break
        hasher.update(force_bytes(data))
    if hasattr(filelike, "seek"):
        filelike.seek(file_pos)
    return hasher.hexdigest()
    def open_file(self):
        close_file = False
        try:
            image_file = self.file
            if self.file.closed:
                if self.is_stored_locally():
                    self.file.open("rb")
                else:
                    storage = self._meta.get_field("file").storage
                    image_file = storage.open(self.file.name, "rb")
                close_file = True
        except IOError as e:
            raise SourceImageIOError(str(e))
        image_file.seek(0)
        try:
            yield image_file
        finally:
            if close_file:
                image_file.close()
