    def _background_reindex_search(self, progress, batch_size):
        target_min_stream_id = progress["target_min_stream_id_inclusive"]
        max_stream_id = progress["max_stream_id_exclusive"]
        rows_inserted = progress.get("rows_inserted", 0)
        TYPES = ["m.room.name", "m.room.message", "m.room.topic"]
        def reindex_search_txn(txn):
            sql = (
                "SELECT stream_ordering, event_id, room_id, type, json, "
                " origin_server_ts FROM events"
                " JOIN event_json USING (room_id, event_id)"
                " WHERE ? <= stream_ordering AND stream_ordering < ?"
                " AND (%s)"
                " ORDER BY stream_ordering DESC"
                " LIMIT ?"
            ) % (" OR ".join("type = '%s'" % (t,) for t in TYPES),)
            txn.execute(sql, (target_min_stream_id, max_stream_id, batch_size))
            rows = self.cursor_to_dict(txn)
            if not rows:
                return 0
            min_stream_id = rows[-1]["stream_ordering"]
            event_search_rows = []
            for row in rows:
                try:
                    event_id = row["event_id"]
                    room_id = row["room_id"]
                    etype = row["type"]
                    stream_ordering = row["stream_ordering"]
                    origin_server_ts = row["origin_server_ts"]
                    try:
                        event_json = json.loads(row["json"])
                        content = event_json["content"]
                    except Exception:
                        continue
                    if etype == "m.room.message":
                        key = "content.body"
                        value = content["body"]
                    elif etype == "m.room.topic":
                        key = "content.topic"
                        value = content["topic"]
                    elif etype == "m.room.name":
                        key = "content.name"
                        value = content["name"]
                    else:
                        raise Exception("unexpected event type %s" % etype)
                except (KeyError, AttributeError):
                    continue
                if not isinstance(value, basestring):
                    continue
                event_search_rows.append(SearchEntry(
                    key=key,
                    value=value,
                    event_id=event_id,
                    room_id=room_id,
                    stream_ordering=stream_ordering,
                    origin_server_ts=origin_server_ts,
                ))
            self.store_search_entries_txn(txn, event_search_rows)
            progress = {
                "target_min_stream_id_inclusive": target_min_stream_id,
                "max_stream_id_exclusive": min_stream_id,
                "rows_inserted": rows_inserted + len(event_search_rows)
            }
            self._background_update_progress_txn(
                txn, self.EVENT_SEARCH_UPDATE_NAME, progress
            )
            return len(event_search_rows)
        result = yield self.runInteraction(
            self.EVENT_SEARCH_UPDATE_NAME, reindex_search_txn
        )
        if not result:
            yield self._end_background_update(self.EVENT_SEARCH_UPDATE_NAME)
        defer.returnValue(result)
