    def build_in_comparator(self):
        left = Expr(self.expr.left, self.context).ir_node
        right = Expr(self.expr.right, self.context).ir_node
        if not left.typ._is_prim_word:
            raise TypeMismatch(
                "`in` not allowed for arrays of non-base types, tracked in issue
            )
        left = unwrap_location(left)
        if isinstance(self.expr.op, vy_ast.In):
            found, not_found = 1, 0
        elif isinstance(self.expr.op, vy_ast.NotIn):
            found, not_found = 0, 1
        else:
            return
        i = IRnode.from_list(self.context.fresh_varname("in_ix"), typ=UINT256_T)
        found_ptr = self.context.new_internal_variable(BoolT())
        ret = ["seq"]
        with left.cache_when_complex("needle") as (b1, left), right.cache_when_complex(
            "haystack"
        ) as (b2, right):
            if right.value == "multi":
                assert len(right.args) > 0
                args = [unwrap_location(val) for val in right.args]
                if isinstance(self.expr.op, vy_ast.In):
                    checks = [["eq", left, val] for val in args]
                    return b1.resolve(b2.resolve(Expr._logical_or(checks)))
                if isinstance(self.expr.op, vy_ast.NotIn):
                    checks = [["ne", left, val] for val in args]
                    return b1.resolve(b2.resolve(Expr._logical_and(checks)))
                return
            ith_element_ptr = get_element_ptr(right, i, array_bounds_check=False)
            ith_element = unwrap_location(ith_element_ptr)
            if isinstance(right.typ, SArrayT):
                len_ = right.typ.count
            else:
                len_ = get_dyn_array_count(right)
            loop_body = [
                "if",
                ["eq", left, ith_element],
                ["seq", ["mstore", found_ptr, found], "break"],
            ]
            loop = ["repeat", i, 0, len_, right.typ.count, loop_body]
            ret.append(["seq", ["mstore", found_ptr, not_found], loop, ["mload", found_ptr]])
            return IRnode.from_list(b1.resolve(b2.resolve(ret)), typ=BoolT())
def _external_call_helper(contract_address, args_ir, call_kwargs, call_expr, context):
    fn_type = call_expr.func._metadata["type"]
    assert fn_type.min_arg_count <= len(args_ir) <= fn_type.max_arg_count
    ret = ["seq"]
    ret.append(eval_once_check(_freshname(call_expr.node_source_code)))
    buf, arg_packer, args_ofst, args_len = _pack_arguments(fn_type, args_ir, context)
    ret_unpacker, ret_ofst, ret_len = _unpack_returndata(
        buf, fn_type, call_kwargs, contract_address, context, call_expr
    )
    ret += arg_packer
    if fn_type.return_type is None and not call_kwargs.skip_contract_check:
        ret.append(_extcodesize_check(contract_address))
    gas = call_kwargs.gas
    value = call_kwargs.value
    use_staticcall = fn_type.mutability in (StateMutability.VIEW, StateMutability.PURE)
    if context.is_constant():
        assert use_staticcall, "typechecker missed this"
    if use_staticcall:
        call_op = ["staticcall", gas, contract_address, args_ofst, args_len, buf, ret_len]
    else:
        call_op = ["call", gas, contract_address, value, args_ofst, args_len, buf, ret_len]
    ret.append(check_external_call(call_op))
    return_t = fn_type.return_type
    if return_t is not None:
        ret.append(ret_unpacker)
    return IRnode.from_list(ret, typ=return_t, location=MEMORY)
UINT256_T = IntegerT(False, 256)
MEMORY = AddrSpace("memory", 32, "mload", "mstore")

class Connection(object):
    def _search_executable(self, executable):
        cmd = distutils.spawn.find_executable(executable)
        if not cmd:
            raise errors.AnsibleError("%s command not found in PATH") % executable
        return cmd
    def list_jails(self):
        p = subprocess.Popen([self.jls_cmd, '-q', 'name'],
                             cwd=self.runner.basedir,
                             stdin=subprocess.PIPE,
                             stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        stdout, stderr = p.communicate()
        return stdout.split()
    def get_jail_path(self):
        p = subprocess.Popen([self.jls_cmd, '-j', self.jail, '-q', 'path'],
                             cwd=self.runner.basedir,
                             stdin=subprocess.PIPE,
                             stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        stdout, stderr = p.communicate()
        return stdout[:-1]
    def __init__(self, runner, host, port, *args, **kwargs):
        self.jail = host
        self.runner = runner
        self.host = host
        self.has_pipelining = False
        self.become_methods_supported=C.BECOME_METHODS
        if os.geteuid() != 0:
            raise errors.AnsibleError("jail connection requires running as root")
        self.jls_cmd = self._search_executable('jls')
        self.jexec_cmd = self._search_executable('jexec')
        if not self.jail in self.list_jails():
            raise errors.AnsibleError("incorrect jail name %s" % self.jail)
        self.host = host
        self.port = port
    def connect(self, port=None):
        ''' connect to the chroot; nothing to do here '''
        vvv("THIS IS A LOCAL CHROOT DIR", host=self.jail)
        return self
    def _generate_cmd(self, executable, cmd):
        if executable:
            local_cmd = [self.jexec_cmd, self.jail, executable, '-c', cmd]
        else:
            local_cmd = '%s "%s" %s' % (self.jexec_cmd, self.jail, cmd)
        return local_cmd
