                write_debug('Lazy loading extractors is disabled')
        if self.params['compat_opts']:
            write_debug('Compatibility options: %s' % ', '.join(self.params['compat_opts']))
        if current_git_head():
            write_debug(f'Git HEAD: {current_git_head()}')
        write_debug(system_identifier())
        exe_versions, ffmpeg_features = FFmpegPostProcessor.get_versions_and_features(self)
        ffmpeg_features = {key for key, val in ffmpeg_features.items() if val}
        if ffmpeg_features:
            exe_versions['ffmpeg'] += ' (%s)' % ','.join(sorted(ffmpeg_features))
        exe_versions['rtmpdump'] = rtmpdump_version()
        exe_versions['phantomjs'] = PhantomJSwrapper._version()
        exe_str = ', '.join(
            f'{exe} {v}' for exe, v in sorted(exe_versions.items()) if v
        ) or 'none'
        write_debug('exe versions: %s' % exe_str)
        from .compat.compat_utils import get_package_info
        from .dependencies import available_dependencies
        write_debug('Optional libraries: %s' % (', '.join(sorted({
            join_nonempty(*get_package_info(m)) for m in available_dependencies.values()
        })) or 'none'))
        self._setup_opener()
        proxy_map = {}
        for handler in self._opener.handlers:
            if hasattr(handler, 'proxies'):
                proxy_map.update(handler.proxies)
        write_debug(f'Proxy map: {proxy_map}')
        for plugin_type, plugins in {'Extractor': plugin_ies, 'Post-Processor': plugin_pps}.items():
            display_list = ['%s%s' % (
                klass.__name__, '' if klass.__name__ == name else f' as {name}')
                for name, klass in plugins.items()]
            if plugin_type == 'Extractor':
                display_list.extend(f'{plugins[-1].IE_NAME.partition("+")[2]} ({parent.__name__})'
                                    for parent, plugins in plugin_ie_overrides.items())
            if not display_list:
                continue
            write_debug(f'{plugin_type} Plugins: {", ".join(sorted(display_list))}')
        plugin_dirs = plugin_directories()
        if plugin_dirs:
            write_debug(f'Plugin directories: {plugin_dirs}')
        if False and self.params.get('call_home'):
            ipaddr = self.urlopen('https://yt-dl.org/ip').read().decode()
            write_debug('Public IP address: %s' % ipaddr)
            latest_version = self.urlopen(
                'https://yt-dl.org/latest/version').read().decode()
            if version_tuple(latest_version) > version_tuple(__version__):
                self.report_warning(
                    'You are using an outdated version (newest version: %s)! '
                    'See https://yt-dl.org/update if you need help updating.' %
                    latest_version)
        subtitles = info_dict.get('requested_subtitles')
    def download(self, filename, info_dict, subtitle=False):
        """Download to a filename using the info from info_dict
        Return True on success and False otherwise
        """
        nooverwrites_and_exists = (
            not self.params.get('overwrites', True)
            and os.path.exists(encodeFilename(filename))
        )
        if not hasattr(filename, 'write'):
            continuedl_and_exists = (
                self.params.get('continuedl', True)
                and os.path.isfile(encodeFilename(filename))
                and not self.params.get('nopart', False)
            )
            if filename != '-' and (nooverwrites_and_exists or continuedl_and_exists):
                self.report_file_already_downloaded(filename)
                self._hook_progress({
                    'filename': filename,
                    'status': 'finished',
                    'total_bytes': os.path.getsize(encodeFilename(filename)),
                }, info_dict)
                self._finish_multiline_status()
                return True, False
        if subtitle:
            sleep_interval = self.params.get('sleep_interval_subtitles') or 0
        else:
            min_sleep_interval = self.params.get('sleep_interval') or 0
            sleep_interval = random.uniform(
                min_sleep_interval, self.params.get('max_sleep_interval') or min_sleep_interval)
        if sleep_interval > 0:
            self.to_screen(f'[download] Sleeping {sleep_interval:.2f} seconds ...')
            time.sleep(sleep_interval)
        info_dict['http_headers'] = dict(traverse_obj(info_dict, (
            'http_headers', {dict.items}, lambda _, pair: pair[0].lower() != 'cookie'))) or None
        ret = self.real_download(filename, info_dict)
        self._finish_multiline_status()
        return ret, True

def set_data_positions(
    vyper_module: vy_ast.Module, storage_layout_overrides: StorageLayout = None
