class GeoFenceClient:
    def run_batch(self, batch: Batch, timeout: int = None) -> bool:
        if batch.length() == 0:
            logger.debug(f"Skipping batch execution {batch.log_name}")
            return False
        logger.debug(f"Running batch {batch.log_name} with {batch.length()} operations")
        try:
            """
            curl -X GET -u admin:geoserver \
                http://<host>:<port>/geoserver/rest/geofence/rules/count.json
            """
            r = requests.post(
                f"{self.baseurl}batch/exec",
                json=batch.get_object(),
                auth=HTTPBasicAuth(self.username, self.pw),
                timeout=timeout or self.timeout,
                verify=False,
            )
            if r.status_code != 200:
                logger.debug(
                    f"Error while running batch {batch.log_name}: [{r.status_code}] - {r.content}"
                    f"\n {batch.get_object()}"
                )
                raise GeofenceException(f"Error while running batch {batch.log_name}: [{r.status_code}]")
            return True
        except Exception as e:
            logger.info(f"Error while requesting batch exec {batch.log_name}")
            logger.debug(f"Error while requesting batch exec {batch.log_name} --> {batch.get_object()}", exc_info=e)
            raise GeofenceException(f"Error while requesting batch execution {batch.log_name}: {e}")
def geoserver_proxy(request, proxy_path, downstream_path, workspace=None, layername=None):
    """
    WARNING: Decorators are applied in the order they appear in the source.
    """
    affected_datasets = None
    allowed_hosts = [
        urlsplit(ogc_server_settings.public_url).hostname,
    ]
    raw_url, headers, access_token, downstream_path = check_geoserver_access(
        request, proxy_path, downstream_path, workspace=workspace, layername=layername, allowed_hosts=allowed_hosts
    )
    url = urlsplit(raw_url)
    if re.match(r"^.*(?<!/rest/)/rest/", url.path) and request.method in ("POST", "PUT", "DELETE"):
        if re.match(r"^.*(?<!/rest/)/rest/.*/?styles.*", url.path):
            logger.debug(f"[geoserver_proxy] Updating Style ---> url {url.geturl()}")
            _style_name, _style_ext = os.path.splitext(os.path.basename(urlsplit(url.geturl()).path))
            _parsed_get_args = dict(parse_qsl(urlsplit(url.geturl()).query))
            if _style_name == "styles.json" and request.method == "PUT":
                if _parsed_get_args.get("name"):
                    _style_name, _style_ext = os.path.splitext(_parsed_get_args.get("name"))
            else:
                _style_name, _style_ext = os.path.splitext(_style_name)
            if not style_change_check(request, url.path, style_name=_style_name, access_token=access_token):
                return HttpResponse(
                    _("You don't have permissions to change style for this layer"),
                    content_type="text/plain",
                    status=401,
                )
            if (
                _style_name != "style-check"
                and (_style_ext == ".json" or _parsed_get_args.get("raw"))
                and not re.match(temp_style_name_regex, _style_name)
            ):
                affected_datasets = style_update(request, raw_url, workspace)
        elif re.match(r"^.*(?<!/rest/)/rest/.*/?layers.*", url.path):
            logger.debug(f"[geoserver_proxy] Updating Dataset ---> url {url.geturl()}")
            try:
                _dataset_name = os.path.splitext(os.path.basename(request.path))[0]
                _dataset = Dataset.objects.get(name=_dataset_name)
                affected_datasets = [_dataset]
            except Exception:
                logger.warn(f"Could not find any Dataset {os.path.basename(request.path)} on DB")
    kwargs = {"affected_datasets": affected_datasets}
    raw_url = unquote(raw_url)
    timeout = getattr(ogc_server_settings, "TIMEOUT") or 60
    response = proxy(
        request,
        url=raw_url,
        response_callback=_response_callback,
        timeout=timeout,
        allowed_hosts=allowed_hosts,
        headers=headers,
        access_token=access_token,
        **kwargs,
    )
    return response
def _datasets_locations(
    instance: Union[Dataset, Map], compute_bbox: bool = False, target_crs: str = "EPSG:3857"
) -> Tuple[List[List], List]:
    """
    Function returning a list mapping instance's datasets to their locations, enabling to construct a minimum
    number of  WMS request for multiple datasets of the same OGC source (ensuring datasets order for Maps)
    :param instance: instance of Dataset or Map models
    :param compute_bbox: flag determining whether a BBOX containing the instance should be computed,
                         based on instance's datasets
    :param target_crs: valid only when compute_bbox is True - CRS of the returned BBOX
    :return: a tuple with a list, which maps datasets to their locations in a correct datasets order
             e.g.
                [
                    ["http://localhost:8080/geoserver/": ["geonode:layer1", "geonode:layer2]]
                ]
             and a list optionally consisting of 5 elements containing west, east, south, north
             instance's boundaries and CRS
    """
    locations = []
    bbox = []
    if isinstance(instance, Dataset):
        locations.append([instance.ows_url or ogc_server_settings.LOCATION, [instance.alternate], []])
        if compute_bbox:
            if instance.ll_bbox_polygon:
                bbox = utils.clean_bbox(instance.ll_bbox, target_crs)
            elif (
                instance.bbox[-1].upper() != "EPSG:3857"
                and target_crs.upper() == "EPSG:3857"
                and utils.exceeds_epsg3857_area_of_use(instance.bbox)
            ):
                bbox = utils.transform_bbox(utils.crop_to_3857_area_of_use(instance.bbox), target_crs)
            else:
                bbox = utils.transform_bbox(instance.bbox, target_crs)
    elif isinstance(instance, Map):
        for map_dataset in instance.maplayers.filter(visibility=True).order_by("order").iterator():
            if not map_dataset.local and not map_dataset.ows_url:
                logger.warning(
                    "Incorrectly defined remote dataset encountered (no OWS URL defined)."
                    "Skipping it in the thumbnail generation."
                )
                continue
            name = get_dataset_name(map_dataset)
            store = map_dataset.store
            workspace = get_dataset_workspace(map_dataset)
            map_dataset_style = map_dataset.current_style
            if store and Dataset.objects.filter(store=store, workspace=workspace, name=name).exists():
                dataset = Dataset.objects.filter(store=store, workspace=workspace, name=name).first()
            elif workspace and Dataset.objects.filter(workspace=workspace, name=name).exists():
                dataset = Dataset.objects.filter(workspace=workspace, name=name).first()
            elif Dataset.objects.filter(alternate=map_dataset.name).exists():
