        right = Expr.parse_value_expr(self.expr.right, self.context)
        if right.value is None:
            return
        if isinstance(self.expr.op, (vy_ast.In, vy_ast.NotIn)):
            if isinstance(right.typ, ArrayLike):
                return self.build_in_comparator()
            return
