        await ctx.send(_("User has been banned from speaking or listening in voice channels."))

class App:
    JINJA_TEMPLATE_GLOBALS = TEMPLATE_GLOBALS
    JINJA_TEMPLATE_FILTERS = TEMPLATE_FILTERS
    JINJA_CONTEXT_PROCESSORS = CONTEXT_PROCESSORS
    FLASK_ERROR_HANDLERS = ERROR_HANDLERS
    FLASK_BLUEPRINTS = BLUEPRINTS
    FLASK_EXTENSIONS = EXTENSIONS
    FLASK_THEMES = THEMES
    def _configure_config(cls, app, develop):
        conf_obj = get_default_config(develop)
        app.config.from_object(conf_obj)
    def _configure_blueprints(cls, app, path_prefix):
        for blueprint in cls.FLASK_BLUEPRINTS:
            url_prefix = path_prefix if not blueprint.url_prefix else None
            app.register_blueprint(blueprint, url_prefix=url_prefix)
    def _configure_extensions(cls, app):
        for extension in cls.FLASK_EXTENSIONS:
            extension.init_app(app)
    def _configure_themes(cls, app, path_prefix=""):
        for theme in cls.FLASK_THEMES:
            theme.init_app(app, path_prefix)
    def _configure_handlers(cls, app):
        """
        Register app handlers.
        """
        for exc, fn in cls.FLASK_ERROR_HANDLERS:
            app.register_error_handler(exc, fn)
        @app.after_request
        def deny_iframe(response):
            response.headers["X-Frame-Options"] = "DENY"
            return response
    def _configure_json_encoding(cls, app):
        try:
            from .helpers import JSONProvider
            app.json = JSONProvider(app)
        except ImportError:
            from .helpers import JSONEncoder
            app.json_encoder = JSONEncoder
    def _configure_templating(cls, app):
        tempdir = app.config["PYLOAD_API"].get_cachedir()
        cache_path = os.path.join(tempdir, "jinja")
        os.makedirs(cache_path, exist_ok=True)
        app.create_jinja_environment()
        app.jinja_env.autoescape = jinja2.select_autoescape(default=True)
        app.jinja_env.bytecode_cache = jinja2.FileSystemBytecodeCache(cache_path)
        for fn in cls.JINJA_TEMPLATE_FILTERS:
            app.add_template_filter(fn)
        for fn in cls.JINJA_TEMPLATE_GLOBALS:
            app.add_template_global(fn)
        for fn in cls.JINJA_CONTEXT_PROCESSORS:
            app.context_processor(fn)
    def _configure_session(cls, app):
        tempdir = app.config["PYLOAD_API"].get_cachedir()
        cache_path = os.path.join(tempdir, "flask")
        os.makedirs(cache_path, exist_ok=True)
        app.config["SESSION_FILE_DIR"] = cache_path
        app.config["SESSION_TYPE"] = "filesystem"
        app.config["SESSION_COOKIE_NAME"] = "pyload_session"
        app.config["SESSION_COOKIE_SAMESITE"] = "None"
        app.config["SESSION_COOKIE_SECURE"] = app.config["PYLOAD_API"].get_config_value("webui", "use_ssl")
        app.config["SESSION_PERMANENT"] = False
        session_lifetime = max(app.config["PYLOAD_API"].get_config_value("webui", "session_lifetime"), 1) * 60
        app.config["PERMANENT_SESSION_LIFETIME"] = session_lifetime
    def _configure_api(cls, app, pycore):
        app.config["PYLOAD_API"] = pycore.api
    def _configure_logging(cls, app, pycore):
        app.logger = pycore.log.getChild("webui")
    def __new__(cls, pycore, develop=False, path_prefix=None):
        app = flask.Flask(__name__)
        cls._configure_logging(app, pycore)
        cls._configure_api(app, pycore)
        cls._configure_config(app, develop)
        cls._configure_templating(app)
        cls._configure_json_encoding(app)
        cls._configure_session(app)
        cls._configure_blueprints(app, path_prefix)
        cls._configure_extensions(app)
        cls._configure_themes(app, path_prefix or "")
        cls._configure_handlers(app)
        WSGIRequestHandler.protocol_version = "HTTP/1.1"
        return app
class WebServerThread(threading.Thread):
    def __init__(self, pycore):
        super().__init__()
        self.daemon = True
        self.pyload = pycore
        self._ = pycore._
        self.develop = self.pyload.config.get("webui", "develop")
        self.use_ssl = self.pyload.config.get("webui", "use_ssl")
        self.certfile = self.pyload.config.get("webui", "ssl_certfile")
        self.keyfile = self.pyload.config.get("webui", "ssl_keyfile")
        self.certchain = self.pyload.config.get("webui", "ssl_certchain") or None
        self.host = self.pyload.config.get("webui", "host")
        self.port = self.pyload.config.get("webui", "port")
        self.prefix = self.pyload.config.get("webui", "prefix")
        self.app = App(self.pyload, self.develop, self.prefix)
        self.log = self.app.logger
    def _run_develop(self):
        self.app.run(self.host, self.port, use_reloader=False)
    def _run_produc(self):
        bind_path = "/"
        bind_addr = (self.host, self.port)
        wsgi_app = wsgi.PathInfoDispatcher({bind_path: self.app})
        self.server = wsgi.Server(bind_addr, wsgi_app, request_queue_size=512)
        if self.use_ssl:
            try:
                self.server.ssl_adapter = BuiltinSSLAdapter(
                    self.certfile, self.keyfile, self.certchain
                )
            except Exception as exc:
                self.log.error(
                    self._("Cannot use HTTPS: {}").format(exc),
                    exc_info=self.pyload.debug,
                    stack_info=self.pyload.debug > 2,
                )
                self.use_ssl = False
        self.server.error_log = lambda *args, **kwargs: self.log.log(
            kwargs.get("level", logging.ERROR), args[0], exc_info=self.pyload.debug
        )
        self.server.start()
    def stop(self):
        if not self.develop:
            self.server.stop()
        else:
            pass
    def run(self):
        if self.use_ssl and self.develop:
            self.log.warning(
                self._(
                    "Development mode does not support HTTPS, please disable development mode to use HTTPS"
                )
            )
            self.use_ssl = False
        self.log.info(
            self._("Starting webserver: {scheme}://{host}:{port}").format(
                scheme="https" if self.use_ssl else "http",
                host=f"[{self.host}]" if ":" in self.host else self.host,
                port=self.port,
            )
        )
        try:
            if self.develop:
                self._run_develop()
            else:
                self._run_produc()
        except OSError as exc:
            if (
                exc.errno in (98, 10013)
                or isinstance(exc.args[0], str)
                and ("Errno 98" in exc.args[0] or "WinError 10048" in exc.args[0])
            ):
                self.log.fatal(
                    self._(
                        "** FATAL ERROR ** Could not start web server - Address Already in Use | Exiting pyLoad"
                    )
                )
                self.pyload.api.kill()
            else:
                raise

class App:
    JINJA_TEMPLATE_GLOBALS = TEMPLATE_GLOBALS
    JINJA_TEMPLATE_FILTERS = TEMPLATE_FILTERS
    JINJA_CONTEXT_PROCESSORS = CONTEXT_PROCESSORS
    FLASK_ERROR_HANDLERS = ERROR_HANDLERS
    FLASK_BLUEPRINTS = BLUEPRINTS
    FLASK_EXTENSIONS = EXTENSIONS
    FLASK_THEMES = THEMES
    def _configure_config(cls, app, develop):
        conf_obj = get_default_config(develop)
        app.config.from_object(conf_obj)
    def _configure_blueprints(cls, app, path_prefix):
        for blueprint in cls.FLASK_BLUEPRINTS:
            url_prefix = path_prefix if not blueprint.url_prefix else None
            app.register_blueprint(blueprint, url_prefix=url_prefix)
    def _configure_extensions(cls, app):
        for extension in cls.FLASK_EXTENSIONS:
            extension.init_app(app)
    def _configure_themes(cls, app, path_prefix=""):
        for theme in cls.FLASK_THEMES:
            theme.init_app(app, path_prefix)
    def _configure_handlers(cls, app):
        """
        Register app handlers.
        """
        for exc, fn in cls.FLASK_ERROR_HANDLERS:
            app.register_error_handler(exc, fn)
        @app.after_request
        def deny_iframe(response):
            response.headers["X-Frame-Options"] = "DENY"
            return response
    def _configure_json_encoding(cls, app):
        try:
            from .helpers import JSONProvider
            app.json = JSONProvider(app)
        except ImportError:
            from .helpers import JSONEncoder
            app.json_encoder = JSONEncoder
    def _configure_templating(cls, app):
        tempdir = app.config["PYLOAD_API"].get_cachedir()
        cache_path = os.path.join(tempdir, "jinja")
        os.makedirs(cache_path, exist_ok=True)
        app.create_jinja_environment()
        app.jinja_env.autoescape = jinja2.select_autoescape(default=True)
        app.jinja_env.bytecode_cache = jinja2.FileSystemBytecodeCache(cache_path)
        for fn in cls.JINJA_TEMPLATE_FILTERS:
            app.add_template_filter(fn)
        for fn in cls.JINJA_TEMPLATE_GLOBALS:
            app.add_template_global(fn)
        for fn in cls.JINJA_CONTEXT_PROCESSORS:
            app.context_processor(fn)
    def _configure_session(cls, app):
        tempdir = app.config["PYLOAD_API"].get_cachedir()
        cache_path = os.path.join(tempdir, "flask")
        os.makedirs(cache_path, exist_ok=True)
        app.config["SESSION_FILE_DIR"] = cache_path
        app.config["SESSION_TYPE"] = "filesystem"
        app.config["SESSION_COOKIE_NAME"] = "pyload_session"
        app.config["SESSION_COOKIE_SAMESITE"] = "Strict"
        app.config["SESSION_COOKIE_SECURE"] = app.config["PYLOAD_API"].get_config_value("webui", "use_ssl")
        app.config["SESSION_PERMANENT"] = False
        session_lifetime = max(app.config["PYLOAD_API"].get_config_value("webui", "session_lifetime"), 1) * 60
        app.config["PERMANENT_SESSION_LIFETIME"] = session_lifetime
    def _configure_api(cls, app, pycore):
        app.config["PYLOAD_API"] = pycore.api
    def _configure_logging(cls, app, pycore):
        app.logger = pycore.log.getChild("webui")
    def __new__(cls, pycore, develop=False, path_prefix=None):
        app = flask.Flask(__name__)
        cls._configure_logging(app, pycore)
        cls._configure_api(app, pycore)
        cls._configure_config(app, develop)
        cls._configure_templating(app)
        cls._configure_json_encoding(app)
        cls._configure_session(app)
        cls._configure_blueprints(app, path_prefix)
        cls._configure_extensions(app)
        cls._configure_themes(app, path_prefix or "")
        cls._configure_handlers(app)
        WSGIRequestHandler.protocol_version = "HTTP/1.1"
        return app
class WebServerThread(threading.Thread):
    def __init__(self, pycore):
        super().__init__()
        self.daemon = True
        self.pyload = pycore
        self._ = pycore._
        self.develop = self.pyload.config.get("webui", "develop")
        self.use_ssl = self.pyload.config.get("webui", "use_ssl")
        self.certfile = self.pyload.config.get("webui", "ssl_certfile")
        self.keyfile = self.pyload.config.get("webui", "ssl_keyfile")
        self.certchain = self.pyload.config.get("webui", "ssl_certchain") or None
        self.host = self.pyload.config.get("webui", "host")
        self.port = self.pyload.config.get("webui", "port")
        self.prefix = self.pyload.config.get("webui", "prefix")
        self.app = App(self.pyload, self.develop, self.prefix)
        self.log = self.app.logger
    def _run_develop(self):
        self.app.run(self.host, self.port, use_reloader=False)
    def _run_produc(self):
        bind_path = "/"
        bind_addr = (self.host, self.port)
        wsgi_app = wsgi.PathInfoDispatcher({bind_path: self.app})
        self.server = wsgi.Server(bind_addr, wsgi_app, request_queue_size=512)
        if self.use_ssl:
            try:
                self.server.ssl_adapter = BuiltinSSLAdapter(
                    self.certfile, self.keyfile, self.certchain
                )
            except Exception as exc:
                self.log.error(
                    self._("Cannot use HTTPS: {}").format(exc),
                    exc_info=self.pyload.debug,
                    stack_info=self.pyload.debug > 2,
                )
                self.use_ssl = False
        self.server.error_log = lambda *args, **kwargs: self.log.log(
            kwargs.get("level", logging.ERROR), args[0], exc_info=self.pyload.debug
        )
        self.server.start()
    def stop(self):
        if not self.develop:
            self.server.stop()
        else:
            pass
    def run(self):
        if self.use_ssl and self.develop:
            self.log.warning(
                self._(
                    "Development mode does not support HTTPS, please disable development mode to use HTTPS"
                )
            )
            self.use_ssl = False
        self.log.info(
            self._("Starting webserver: {scheme}://{host}:{port}").format(
                scheme="https" if self.use_ssl else "http",
                host=f"[{self.host}]" if ":" in self.host else self.host,
                port=self.port,
            )
        )
        try:
            if self.develop:
                self._run_develop()
            else:
                self._run_produc()
        except OSError as exc:
            if (
                exc.errno in (98, 10013)
                or isinstance(exc.args[0], str)
                and ("Errno 98" in exc.args[0] or "WinError 10048" in exc.args[0])
            ):
                self.log.fatal(
                    self._(
                        "** FATAL ERROR ** Could not start web server - Address Already in Use | Exiting pyLoad"
                    )
                )
                self.pyload.api.kill()
            else:
                raise

async def start_transient_service(
    unit_name,
    cmd,
    args,
    working_dir,
    environment_variables=None,
    properties=None,
    uid=None,
    gid=None,
    slice=None,
):
    """
    Start a systemd transient service with given paramters
    """
    run_cmd = [
        'systemd-run',
        '--unit', unit_name,
    ]
    if properties:
        for key, value in properties.items():
            if isinstance(value, list):
                run_cmd += ['--property={}={}'.format(key, v) for v in value]
            else:
                run_cmd.append('--property={}={}'.format(key, value))
    if environment_variables:
        run_cmd += [
            '--setenv={}={}'.format(key, value)
            for key, value in environment_variables.items()
        ]
    if uid is not None:
        run_cmd += ['--uid', str(uid)]
    if gid is not None:
        run_cmd += ['--gid', str(gid)]
    if slice is not None:
        run_cmd += ['--slice={}'.format(slice)]
    run_cmd += [
        '/bin/bash',
        '-c',
        "cd {wd} && exec {cmd} {args}".format(
            wd=shlex.quote(working_dir),
            cmd=' '.join([shlex.quote(c) for c in cmd]),
            args=' '.join([shlex.quote(a) for a in args])
        )
    ]
    proc = await asyncio.create_subprocess_exec(*run_cmd)
    return await proc.wait()

