            last_sent_message = None
    @processor(Action.SendMessage)
    async def send_message(params: models.SendMessage):
        nonlocal last_sent_message
        default_values = 0
        for key in params.dict():
            if key == "edit_message_id":
                continue
            attr = getattr(params, key)
            if attr is None:
                default_values += 1
                setattr(params, key, discord.Embed.Empty)
            elif isinstance(attr, str):
                setattr(params, key, safe_sub(attr))
        is_user = False
        if params.id.isdigit():
            params.id = int(params.id)
            destination = discord.utils.get(guild.text_channels, id=params.id)
            if destination is None:
                destination = guild.get_member(params.id)
                if destination is None:
                    cog.send_to_monitor(guild, f"[Warden] ({self.name}): Failed to send message, "
                                                f"I could not find the recipient.")
                    return
                else:
                    is_user = True
        else:
            destination = discord.utils.get(guild.text_channels, name=params.id)
            if destination is None:
                raise ExecutionError(f"[Warden] ({self.name}): Failed to send message, "
                                    f"'{params.id}' is not a valid channel name.")
        em = None
        no_embed = default_values >= 10
        if no_embed and not params.content:
            raise ExecutionError(f"[Warden] ({self.name}): I have no content and "
                                  "no embed to send.")
        if no_embed is False:
            em = discord.Embed(title=params.title,
                            description=params.description,
                            url=params.url)
            if params.author_name:
                em.set_author(name=params.author_name, url=params.author_url,
                            icon_url=params.author_icon_url)
            em.set_image(url=params.image)
            em.set_thumbnail(url=params.thumbnail)
            em.set_footer(text=params.footer_text, icon_url=params.footer_icon_url)
            for field in params.fields:
                em.add_field(name=safe_sub(field.name),
                            value=safe_sub(field.value),
                            inline=field.inline)
            if params.add_timestamp:
                em.timestamp = utcnow()
            if params.color is True:
                em.color = await cog.bot.get_embed_color(destination)
            elif not params.color:
                pass
            else:
                em.color = discord.Colour(params.color)
        mentions = discord.AllowedMentions(everyone=params.allow_mass_mentions, roles=True, users=True,
                                           replied_user=params.ping_on_reply)
        if params.edit_message_id:
            params.edit_message_id = safe_sub(params.edit_message_id)
        if isinstance(destination, discord.Member):
            destination = destination.dm_channel if destination.dm_channel else await destination.create_dm()
        reference = None
        if params.reply_message_id:
            params.reply_message_id = safe_sub(params.reply_message_id)
            if params.reply_message_id.isdigit():
                reference = destination.get_partial_message(int(params.reply_message_id))
        if not params.edit_message_id:
            try:
                last_sent_message = await destination.send(params.content, embed=em, allowed_mentions=mentions,
                                                           reference=reference)
            except (discord.HTTPException, discord.Forbidden) as e:
                if is_user is False:
                    raise ExecutionError(f"[Warden] ({self.name}): Failed to deliver message "
                                        f"to channel
        else:
            try:
                partial_msg = destination.get_partial_message(int(params.edit_message_id))
                await partial_msg.edit(content=params.content if params.content else None,
                                       embed=em, allowed_mentions=mentions)
            except (discord.HTTPException, discord.Forbidden) as e:
                raise ExecutionError(f"[Warden] ({self.name}): Failed to edit message "
                                    f"in channel
            except ValueError:
                raise ExecutionError(f"[Warden] ({self.name}): Failed to edit message. "
                                    f"{params.edit_message_id} is not a valid ID")
    @processor(Action.GetUserInfo)
    async def get_user_info(params: models.GetUserInfo):
        params.id = safe_sub(params.id)
        if not params.id.isdigit():
            raise ExecutionError(f"{params.id} is not a valid ID.")
        member = guild.get_member(int(params.id))
        if not member:
            raise ExecutionError(f"Member {params.id} not found.")
        for target, attr in params.mapping.items():
            if attr.startswith("_") or "." in attr:
                raise ExecutionError(f"You cannot access internal attributes.")
            attr = attr.lower()
            if attr == "rank":
                value = await cog.rank_user(member)
                value = value.value
            elif attr == "is_staff":
                value = await cog.bot.is_mod(member)
            elif attr == "is_helper":
                value = await cog.is_helper(member)
            elif attr == "message_count":
                value = await cog.get_total_recorded_messages(member)
            else:
                value = getattr(member, attr, None)
                if value is None:
                    raise ExecutionError(f"Attribute \"{attr}\" does not exist.")
            if isinstance(value, bool):
                value = str(value).lower()
            elif isinstance(value, datetime.datetime):
                value = value.strftime("%Y/%m/%d %H:%M:%S")
            elif isinstance(value, discord.BaseActivity):
                value = value.name if value.name is not None else "none"
            elif isinstance(value, discord.Spotify):
                value = "none"
            elif isinstance(value, (str, int, discord.Asset, discord.Status)):
                value = str(value)
            else:
                raise ExecutionError(f"Attribute \"{attr}\" not supported.")
            templates_vars[safe_sub(target)] = value
    @processor(Action.Exit)
    async def exit(params: models.IsNone):
        raise StopExecution("Exiting.")
    @processor(Action.VarAssign)
    async def assign(params: models.VarAssign):
        if params.evaluate:
            params.value = safe_sub(params.value)
        templates_vars[safe_sub(params.var_name)] = params.value
    @processor(Action.VarAssignRandom)
    async def assign_random(params: models.VarAssignRandom):
        choices = []
        weights = []
        if isinstance(params.choices, list):
            choices = params.choices
        else:
            for k, v in params.choices.items():
                choices.append(k)
                weights.append(v)
        choice = random.choices(choices, weights=weights or None, k=1)[0]
        if params.evaluate:
            choice = safe_sub(choice)
        templates_vars[safe_sub(params.var_name)] = choice
    @processor(Action.VarReplace)
    async def var_replace(params: models.VarReplace):
        var_name = safe_sub(params.var_name)
        var = templates_vars.get(var_name, None)
        if var is None:
            raise ExecutionError(f"Variable \"{var_name}\" does not exist.")
        to_sub = []
        if isinstance(params.strings, str):
            to_sub.append(params.strings)
        else:
            to_sub = params.strings
        for sub in to_sub:
            var = var.replace(sub, params.substring)
        templates_vars[var_name] = var
    @processor(Action.VarSplit)
    async def var_split(params: models.VarSplit):
        var_name = safe_sub(params.var_name)
        var = templates_vars.get(var_name, None)
        if var is None:
            raise ExecutionError(f"Variable \"{var_name}\" does not exist.")
        sequences = var.split(params.separator, maxsplit=params.max_split)
        for i, var in enumerate(params.split_into):
            try:
                templates_vars[var] = sequences[i]
            except IndexError:
                templates_vars[var] = ""
    @processor(Action.VarTransform)
    async def var_transform(params: models.VarTransform):
        var_name = safe_sub(params.var_name)
        var = templates_vars.get(var_name, None)
        if var is None:
            raise ExecutionError(f"Variable \"{var_name}\" does not exist.")
        operation = params.operation.lower()
        if operation == "capitalize":
            var = var.capitalize()
        elif operation == "lowercase":
            var = var.lower()
        elif operation == "reverse":
            var = var[::-1]
        elif operation == "uppercase":
            var = var.upper()
        elif operation == "title":
            var = var.title()
        templates_vars[var_name] = var
    @processor(Action.VarSlice)
    async def var_slice(params: models.VarSlice):
        var_name = safe_sub(params.var_name)
        var = templates_vars.get(var_name, None)
        if var is None:
            raise ExecutionError(f"Variable \"{var_name}\" does not exist.")
        var = var[params.index:params.end_index:params.step]
        if params.slice_into:
            templates_vars[safe_sub(params.slice_into)] = var
        else:
            templates_vars[var_name] = var
    @processor(Action.NoOp)
    async def no_op(params: models.IsNone):
        pass
    if debug:
        for action in Action:
            if action not in processors:
                raise ExecutionError(f"{action.value} does not have a processor.")
    async def process_action(action, value):
        self.last_action = action
        if debug and action not in ALLOWED_DEBUG_ACTIONS:
            return
        params = model_validator(action, value)
        try:
            processor_func = processors[action]
        except KeyError:
            raise ExecutionError(f"Unhandled action '{action.value}'.")
        await processor_func(params)
    last_cond_action_result = None
    for entry in self.actions:
        for enum, value in entry.items():
            enum = self._get_actions_enum(enum)
            if isinstance(enum, Action):
                try:
                    await process_action(enum, value)
                except StopExecution:
                    return bool(last_expel_action)
            elif isinstance(enum, Condition):
                _eval = await self._evaluate_conditions([{enum.value: value}],
                                                        cog=cog, user=user, message=message,
                                                        guild=guild, templates_vars=templates_vars,
                                                        debug=debug)
                last_cond_action_result = _eval[0]
            elif isinstance(enum, ConditionBlock):
                _eval = await self._evaluate_conditions_block(block=[{enum.value: value}],
                                                              cog=cog, user=user, message=message,
                                                              guild=guild, templates_vars=templates_vars,
                                                              debug=debug)
                last_cond_action_result = bool(_eval)
            elif isinstance(enum, ConditionalActionBlock):
                is_true = enum == ConditionalActionBlock.IfTrue and last_cond_action_result is True
                is_false = enum == ConditionalActionBlock.IfFalse and last_cond_action_result is False
                if is_true or is_false:
                    for raw_action in value:
                        for action, subvalue in raw_action.items():
                            action = self._get_actions_enum(action)
                            try:
                                await process_action(action, subvalue)
                            except StopExecution:
                                return bool(last_expel_action)
    return bool(last_expel_action)

        check_prereg_key(request, confirmation_key)
def check_prereg_key(request: HttpRequest, confirmation_key: str) -> PreregistrationUser:
    """
    Checks if the Confirmation key is valid, returning the PreregistrationUser object in case of success
    and raising an appropriate ConfirmationKeyError otherwise.
    """
    confirmation_types = [
        Confirmation.USER_REGISTRATION,
        Confirmation.INVITATION,
        Confirmation.REALM_CREATION,
    ]
    prereg_user = get_object_from_key(confirmation_key, confirmation_types, mark_object_used=False)
    assert isinstance(prereg_user, PreregistrationUser)
    assert prereg_user.created_user is None
    return prereg_user
def accounts_register(
    request: HttpRequest,
    key: str = REQ(default=""),
    timezone: str = REQ(default="", converter=to_timezone_or_empty),
    from_confirmation: Optional[str] = REQ(default=None),
    form_full_name: Optional[str] = REQ("full_name", default=None),
    source_realm_id: Optional[int] = REQ(
        default=None, converter=to_converted_or_fallback(to_non_negative_int, None)
    ),
) -> HttpResponse:
    try:
        prereg_user = check_prereg_key(request, key)
    except ConfirmationKeyError as e:
        return render_confirmation_key_error(request, e)
    email = prereg_user.email
    realm_creation = prereg_user.realm_creation
    password_required = prereg_user.password_required
    role = prereg_user.invited_as
    if realm_creation:
        role = UserProfile.ROLE_REALM_OWNER
    try:
        validators.validate_email(email)
    except ValidationError:
        return render(request, "zerver/invalid_email.html", context={"invalid_email": True})
    if realm_creation:
        realm = None
    else:
        assert prereg_user.realm is not None
        if get_subdomain(request) != prereg_user.realm.string_id:
            return render_confirmation_key_error(
                request, ConfirmationKeyError(ConfirmationKeyError.DOES_NOT_EXIST)
            )
        realm = prereg_user.realm
        try:
            email_allowed_for_realm(email, realm)
        except DomainNotAllowedForRealmError:
            return render(
                request,
                "zerver/invalid_email.html",
                context={"realm_name": realm.name, "closed_domain": True},
            )
        except DisposableEmailError:
            return render(
                request,
                "zerver/invalid_email.html",
                context={"realm_name": realm.name, "disposable_emails_not_allowed": True},
            )
        except EmailContainsPlusError:
            return render(
                request,
                "zerver/invalid_email.html",
                context={"realm_name": realm.name, "email_contains_plus": True},
            )
        if realm.deactivated:
            return redirect_to_deactivation_notice()
        try:
            validate_email_not_already_in_realm(realm, email)
        except ValidationError:
            return redirect_to_email_login_url(email)
        if settings.BILLING_ENABLED:
            try:
                check_spare_licenses_available_for_registering_new_user(realm, email, role=role)
            except LicenseLimitError:
                return render(request, "zerver/no_spare_licenses.html")
    name_validated = False
    require_ldap_password = False
    if from_confirmation:
        try:
            del request.session["authenticated_full_name"]
        except KeyError:
            pass
        ldap_full_name = None
        if settings.POPULATE_PROFILE_VIA_LDAP:
            for backend in get_backends():
                if isinstance(backend, LDAPBackend):
                    try:
                        ldap_username = backend.django_to_ldap_username(email)
                    except NoMatchingLDAPUserError:
                        logging.warning("New account email %s could not be found in LDAP", email)
                        break
                    ldap_user = _LDAPUser(backend, ldap_username)
                    try:
                        ldap_full_name = backend.get_mapped_name(ldap_user)
                    except TypeError:
                        break
                    require_ldap_password = isinstance(backend, ZulipLDAPAuthBackend)
                    break
        if ldap_full_name:
            form = RegistrationForm({"full_name": ldap_full_name}, realm_creation=realm_creation)
            request.session["authenticated_full_name"] = ldap_full_name
            name_validated = True
        elif realm is not None and realm.is_zephyr_mirror_realm:
            hesiod_name = compute_mit_user_fullname(email)
            form = RegistrationForm(
                initial={"full_name": hesiod_name if "@" not in hesiod_name else ""},
                realm_creation=realm_creation,
            )
            name_validated = True
        elif prereg_user.full_name:
            if prereg_user.full_name_validated:
                request.session["authenticated_full_name"] = prereg_user.full_name
                name_validated = True
                form = RegistrationForm(
                    {"full_name": prereg_user.full_name}, realm_creation=realm_creation
                )
            else:
                form = RegistrationForm(
                    initial={"full_name": prereg_user.full_name}, realm_creation=realm_creation
                )
        elif form_full_name is not None:
            form = RegistrationForm(
                initial={"full_name": form_full_name},
                realm_creation=realm_creation,
            )
        else:
            form = RegistrationForm(realm_creation=realm_creation)
    else:
        postdata = request.POST.copy()
        if name_changes_disabled(realm):
            try:
                postdata.update(full_name=request.session["authenticated_full_name"])
                name_validated = True
            except KeyError:
                pass
        form = RegistrationForm(postdata, realm_creation=realm_creation)
    if not (password_auth_enabled(realm) and password_required):
        form["password"].field.required = False
    if form.is_valid():
        if password_auth_enabled(realm) and form["password"].field.required:
            password = form.cleaned_data["password"]
        else:
            password = None
        if realm_creation:
            string_id = form.cleaned_data["realm_subdomain"]
            realm_name = form.cleaned_data["realm_name"]
            realm_type = form.cleaned_data["realm_type"]
            is_demo_org = form.cleaned_data["is_demo_organization"]
            realm = do_create_realm(
                string_id, realm_name, org_type=realm_type, is_demo_organization=is_demo_org
            )
        assert realm is not None
        full_name = form.cleaned_data["full_name"]
        enable_marketing_emails = form.cleaned_data["enable_marketing_emails"]
        default_stream_group_names = request.POST.getlist("default_stream_group")
        default_stream_groups = lookup_default_stream_groups(default_stream_group_names, realm)
        if source_realm_id is not None:
            source_profile: Optional[UserProfile] = get_source_profile(email, source_realm_id)
        else:
            source_profile = None
        if not realm_creation:
            try:
                existing_user_profile: Optional[UserProfile] = get_user_by_delivery_email(
                    email, realm
                )
            except UserProfile.DoesNotExist:
                existing_user_profile = None
        else:
            existing_user_profile = None
        user_profile: Optional[UserProfile] = None
        return_data: Dict[str, bool] = {}
        if ldap_auth_enabled(realm):
            user = authenticate(
                request=request,
                username=email,
                password=password,
                realm=realm,
                prereg_user=prereg_user,
                return_data=return_data,
            )
            if user is None:
                can_use_different_backend = email_auth_enabled(realm) or (
                    len(get_external_method_dicts(realm)) > 0
                )
                if settings.LDAP_APPEND_DOMAIN:
                    can_use_different_backend = can_use_different_backend and (
                        not email_belongs_to_ldap(realm, email)
                    )
                if return_data.get("no_matching_ldap_user") and can_use_different_backend:
                    pass
                else:
                    view_url = reverse("login")
                    query = urlencode({"email": email})
                    redirect_url = append_url_query_string(view_url, query)
                    return HttpResponseRedirect(redirect_url)
            else:
                assert isinstance(user, UserProfile)
                user_profile = user
                if not realm_creation:
                    return login_and_go_to_home(request, user_profile)
        if existing_user_profile is not None and existing_user_profile.is_mirror_dummy:
            user_profile = existing_user_profile
            do_activate_mirror_dummy_user(user_profile, acting_user=user_profile)
            do_change_password(user_profile, password)
            do_change_full_name(user_profile, full_name, user_profile)
            do_change_user_setting(user_profile, "timezone", timezone, acting_user=user_profile)
            do_change_user_setting(
                user_profile,
                "default_language",
                get_default_language_for_new_user(request, realm),
                acting_user=None,
            )
        if user_profile is None:
            user_profile = do_create_user(
                email,
                password,
                realm,
                full_name,
                prereg_user=prereg_user,
                role=role,
                tos_version=settings.TERMS_OF_SERVICE_VERSION,
                timezone=timezone,
                default_language=get_default_language_for_new_user(request, realm),
                default_stream_groups=default_stream_groups,
                source_profile=source_profile,
                realm_creation=realm_creation,
                acting_user=None,
                enable_marketing_emails=enable_marketing_emails,
            )
        if realm_creation:
            return redirect_and_log_into_subdomain(
                ExternalAuthResult(user_profile=user_profile, data_dict={"is_realm_creation": True})
            )
        auth_result = authenticate(
            username=user_profile.delivery_email,
            realm=realm,
            return_data=return_data,
            use_dummy_backend=True,
        )
        if return_data.get("invalid_subdomain"):
            logging.error(
                "Subdomain mismatch in registration %s: %s",
                realm.subdomain,
                user_profile.delivery_email,
            )
            return redirect("/")
        assert isinstance(auth_result, UserProfile)
        return login_and_go_to_home(request, auth_result)
    return render(
        request,
        "zerver/register.html",
        context={
            "form": form,
            "email": email,
            "key": key,
            "full_name": request.session.get("authenticated_full_name", None),
            "lock_name": name_validated and name_changes_disabled(realm),
            "creating_new_team": realm_creation,
            "password_required": password_auth_enabled(realm) and password_required,
            "require_ldap_password": require_ldap_password,
            "password_auth_enabled": password_auth_enabled(realm),
            "root_domain_available": is_root_domain_available(),
            "default_stream_groups": [] if realm is None else get_default_stream_groups(realm),
            "accounts": get_accounts_for_email(email),
            "MAX_REALM_NAME_LENGTH": str(Realm.MAX_REALM_NAME_LENGTH),
            "MAX_NAME_LENGTH": str(UserProfile.MAX_NAME_LENGTH),
            "MAX_PASSWORD_LENGTH": str(form.MAX_PASSWORD_LENGTH),
            "MAX_REALM_SUBDOMAIN_LENGTH": str(Realm.MAX_REALM_SUBDOMAIN_LENGTH),
            "corporate_enabled": settings.CORPORATE_ENABLED,
            "sorted_realm_types": sorted(
                Realm.ORG_TYPES.values(), key=lambda d: d["display_order"]
            ),
        },
    )
def login_and_go_to_home(request: HttpRequest, user_profile: UserProfile) -> HttpResponse:
    mobile_flow_otp = get_expirable_session_var(
        request.session, "registration_mobile_flow_otp", delete=True
    )
    desktop_flow_otp = get_expirable_session_var(
        request.session, "registration_desktop_flow_otp", delete=True
    )
    if mobile_flow_otp is not None:
        return finish_mobile_flow(request, user_profile, mobile_flow_otp)
    elif desktop_flow_otp is not None:
        return finish_desktop_flow(request, user_profile, desktop_flow_otp)
    do_login(request, user_profile)
    return HttpResponseRedirect(mark_sanitized(user_profile.realm.uri) + reverse("home"))
def realm_redirect(request: HttpRequest, next: str = REQ(default="")) -> HttpResponse:
    if request.method == "POST":
        form = RealmRedirectForm(request.POST)
        if form.is_valid():
            subdomain = form.cleaned_data["subdomain"]
            realm = get_realm(subdomain)
            redirect_to = get_safe_redirect_to(next, realm.uri)
            return HttpResponseRedirect(redirect_to)
    else:
        form = RealmRedirectForm()
    return render(request, "zerver/realm_redirect.html", context={"form": form})
def validate_email_not_already_in_realm(
    target_realm: Realm, email: str, verbose: bool = True
) -> None:
    """
    NOTE:
        Only use this to validate that a single email
        is not already used in the realm.
        We should start using bulk_check_new_emails()
        for any endpoint that takes multiple emails,
        such as the "invite" interface.
    """
    error_dict = get_existing_user_errors(target_realm, {email}, verbose)
    for key, error_info in error_dict.items():
        assert key == email
        msg, deactivated = error_info
        raise ValidationError(msg)
def do_create_realm(
    string_id: str,
    name: str,
    *,
    emails_restricted_to_domains: Optional[bool] = None,
    email_address_visibility: Optional[int] = None,
    description: Optional[str] = None,
    invite_required: Optional[bool] = None,
    plan_type: Optional[int] = None,
    org_type: Optional[int] = None,
    date_created: Optional[datetime.datetime] = None,
    is_demo_organization: bool = False,
    enable_read_receipts: Optional[bool] = None,
    enable_spectator_access: Optional[bool] = None,
) -> Realm:
    if string_id == settings.SOCIAL_AUTH_SUBDOMAIN:
        raise AssertionError("Creating a realm on SOCIAL_AUTH_SUBDOMAIN is not allowed!")
    if Realm.objects.filter(string_id=string_id).exists():
        raise AssertionError(f"Realm {string_id} already exists!")
    if not server_initialized():
        logging.info("Server not yet initialized. Creating the internal realm first.")
        create_internal_realm()
    kwargs: Dict[str, Any] = {}
    if emails_restricted_to_domains is not None:
        kwargs["emails_restricted_to_domains"] = emails_restricted_to_domains
    if email_address_visibility is not None:
        kwargs["email_address_visibility"] = email_address_visibility
    if description is not None:
        kwargs["description"] = description
    if invite_required is not None:
        kwargs["invite_required"] = invite_required
    if plan_type is not None:
        kwargs["plan_type"] = plan_type
    if org_type is not None:
        kwargs["org_type"] = org_type
    if enable_spectator_access is not None:
        if enable_spectator_access:
            assert plan_type != Realm.PLAN_TYPE_LIMITED
            assert plan_type is not None or not settings.BILLING_ENABLED
        kwargs["enable_spectator_access"] = enable_spectator_access
    if date_created is not None:
        assert not settings.PRODUCTION
        kwargs["date_created"] = date_created
    if enable_read_receipts is not None:
        kwargs["enable_read_receipts"] = enable_read_receipts
    else:
        kwargs["enable_read_receipts"] = (
            invite_required is None or invite_required is True or emails_restricted_to_domains
        )
    with transaction.atomic():
        realm = Realm(string_id=string_id, name=name, **kwargs)
        if is_demo_organization:
            realm.demo_organization_scheduled_deletion_date = (
                realm.date_created + datetime.timedelta(days=settings.DEMO_ORG_DEADLINE_DAYS)
            )
        set_realm_permissions_based_on_org_type(realm)
        realm.save()
        RealmAuditLog.objects.create(
            acting_user=None,
            realm=realm,
            event_type=RealmAuditLog.REALM_CREATED,
            event_time=realm.date_created,
        )
        RealmUserDefault.objects.create(realm=realm)
        create_system_user_groups_for_realm(realm)
    notifications_stream = ensure_stream(
        realm,
        Realm.DEFAULT_NOTIFICATION_STREAM_NAME,
        stream_description="Everyone is added to this stream by default. Welcome! :octopus:",
        acting_user=None,
    )
    realm.notifications_stream = notifications_stream
    DefaultStream.objects.create(stream=notifications_stream, realm=realm)
    signup_notifications_stream = ensure_stream(
        realm,
        Realm.INITIAL_PRIVATE_STREAM_NAME,
        invite_only=True,
        stream_description="A private stream for core team members.",
        acting_user=None,
    )
    realm.signup_notifications_stream = signup_notifications_stream
    realm.save(update_fields=["notifications_stream", "signup_notifications_stream"])
    if plan_type is None and settings.BILLING_ENABLED:
        do_change_realm_plan_type(realm, Realm.PLAN_TYPE_LIMITED, acting_user=None)
    admin_realm = get_realm(settings.SYSTEM_BOT_REALM)
    sender = get_system_bot(settings.NOTIFICATION_BOT, admin_realm.id)
    signup_message = _("Signups enabled")
    try:
        signups_stream = get_signups_stream(admin_realm)
        topic = realm.display_subdomain
        internal_send_stream_message(
            sender,
            signups_stream,
            topic,
            signup_message,
        )
    except Stream.DoesNotExist:
        pass
    setup_realm_internal_bots(realm)
    return realm
def realm_reactivation(request: HttpRequest, confirmation_key: str) -> HttpResponse:
    try:
        obj = get_object_from_key(
            confirmation_key, [Confirmation.REALM_REACTIVATION], mark_object_used=True
        )
    except ConfirmationKeyError:
        return render(request, "zerver/realm_reactivation_link_error.html", status=404)
    assert isinstance(obj, RealmReactivationStatus)
    realm = obj.realm
    do_reactivate_realm(realm)
    context = {"realm": realm}
    return render(request, "zerver/realm_reactivation.html", context)
def remote_user_jwt(request: HttpRequest) -> HttpResponse:
    subdomain = get_subdomain(request)
    try:
        key = settings.JWT_AUTH_KEYS[subdomain]["key"]
        algorithms = settings.JWT_AUTH_KEYS[subdomain]["algorithms"]
    except KeyError:
        raise JsonableError(_("Auth key for this subdomain not found."))
    try:
        json_web_token = request.POST["json_web_token"]
        options = {"verify_signature": True}
        payload = jwt.decode(json_web_token, key, algorithms=algorithms, options=options)
    except KeyError:
        raise JsonableError(_("No JSON web token passed in request"))
    except jwt.InvalidTokenError:
        raise JsonableError(_("Bad JSON web token"))
    remote_user = payload.get("user", None)
    if remote_user is None:
        raise JsonableError(_("No user specified in JSON web token claims"))
    email_domain = payload.get("realm", None)
    if email_domain is None:
        raise JsonableError(_("No organization specified in JSON web token claims"))
    email = Address(username=remote_user, domain=email_domain).addr_spec
    try:
        realm = get_realm(subdomain)
    except Realm.DoesNotExist:
        raise JsonableError(_("Wrong subdomain"))
    user_profile = authenticate(username=email, realm=realm, use_dummy_backend=True)
    if user_profile is None:
        result = ExternalAuthResult(
            data_dict={"email": email, "full_name": remote_user, "subdomain": realm.subdomain}
        )
    else:
        assert isinstance(user_profile, UserProfile)
        result = ExternalAuthResult(user_profile=user_profile)
    return login_or_register_remote_user(request, result)
