            os.environ['PIP_EXISTS_ACTION'] = ''.join(options.exists_action)
        if options.allow_no_ssl:
            os.environ['PIP_ALLOW_NO_SSL'] = '1'
        if options.cert_path:
            os.environ['PIP_CERT_PATH'] = options.cert_path
