    allowed_hosts = [
        urlsplit(ogc_server_settings.public_url).hostname,
    ]
    raw_url, headers, access_token, downstream_path = check_geoserver_access(
        request, proxy_path, downstream_path, workspace=workspace, layername=layername, allowed_hosts=allowed_hosts
    )
    url = urlsplit(raw_url)
    if re.match(r"^.*(?<!/rest/)/rest/", url.path) and request.method in ("POST", "PUT", "DELETE"):
        if re.match(r"^.*(?<!/rest/)/rest/.*/?styles.*", url.path):
            logger.debug(f"[geoserver_proxy] Updating Style ---> url {url.geturl()}")
            _style_name, _style_ext = os.path.splitext(os.path.basename(urlsplit(url.geturl()).path))
            _parsed_get_args = dict(parse_qsl(urlsplit(url.geturl()).query))
            if _style_name == "styles.json" and request.method == "PUT":
                if _parsed_get_args.get("name"):
                    _style_name, _style_ext = os.path.splitext(_parsed_get_args.get("name"))
            else:
                _style_name, _style_ext = os.path.splitext(_style_name)
            if not style_change_check(request, url.path, style_name=_style_name, access_token=access_token):
                return HttpResponse(
                    _("You don't have permissions to change style for this layer"),
                    content_type="text/plain",
                    status=401,
                )
            if (
                _style_name != "style-check"
                and (_style_ext == ".json" or _parsed_get_args.get("raw"))
                and not re.match(temp_style_name_regex, _style_name)
            ):
                affected_datasets = style_update(request, raw_url, workspace)
        elif re.match(r"^.*(?<!/rest/)/rest/.*/?layers.*", url.path):
            logger.debug(f"[geoserver_proxy] Updating Dataset ---> url {url.geturl()}")
            try:
                _dataset_name = os.path.splitext(os.path.basename(request.path))[0]
                _dataset = Dataset.objects.get(name=_dataset_name)
                affected_datasets = [_dataset]
            except Exception:
                logger.warn(f"Could not find any Dataset {os.path.basename(request.path)} on DB")
    kwargs = {"affected_datasets": affected_datasets}
    raw_url = unquote(raw_url)
    timeout = getattr(ogc_server_settings, "TIMEOUT") or 60
    response = proxy(
        request,
        url=raw_url,
        response_callback=_response_callback,
        timeout=timeout,
        allowed_hosts=allowed_hosts,
        headers=headers,
        access_token=access_token,
        **kwargs,
    )
    return response
class DownloadHandler:
    def process_dowload(self, resource):
        """
        Generate the response object
        """
        if not settings.USE_GEOSERVER:
            return HttpResponseRedirect(reverse("download", args=[resource.id]))
        download_format = self.request.GET.get("export_format")
        if download_format and not wps_format_is_supported(download_format, resource.subtype):
            logger.error("The format provided is not valid for the selected resource")
            return JsonResponse({"error": "The format provided is not valid for the selected resource"}, status=500)
        _format = "application/zip" if resource.is_vector() else "image/tiff"
        tpl = get_template("geoserver/dataset_download.xml")
        ctx = {"alternate": resource.alternate, "download_format": download_format or _format}
        payload = tpl.render(ctx)
        client = HttpClient()
        headers = {"Content-type": "application/xml", "Accept": "application/xml"}
        url = f"{settings.OGC_SERVER['default']['LOCATION']}ows?service=WPS&version=1.0.0&REQUEST=Execute"
        if not self.request.user.is_anonymous:
            access_token = get_or_create_token(self.request.user)
            url += f"&access_token={access_token}"
        response, content = client.request(url=url, data=payload, method="post", headers=headers)
        if not response or response.status_code != 200:
            logger.error(f"Download dataset exception: error during call with GeoServer: {content}")
            return JsonResponse(
                {"error": "Download dataset exception: error during call with GeoServer"},
                status=500,
            )
        namespaces = {"ows": "http://www.opengis.net/ows/1.1", "wps": "http://www.opengis.net/wps/1.0.0"}
        response_type = response.headers.get("Content-Type")
        if response_type == "text/xml":
            content = ET.fromstring(response.text)
            exc = content.find("*//ows:Exception", namespaces=namespaces) or content.find(
                "ows:Exception", namespaces=namespaces
            )
            if exc:
                exc_text = exc.find("ows:ExceptionText", namespaces=namespaces)
                logger.error(f"{exc.attrib.get('exceptionCode')} {exc_text.text}")
                return JsonResponse({"error": f"{exc.attrib.get('exceptionCode')}: {exc_text.text}"}, status=500)
        return_response = fetch_response_headers(
            HttpResponse(content=response.content, status=response.status_code, content_type=download_format),
            response.headers,
        )
        return_response.headers["Content-Type"] = download_format or _format
        return return_response
